from importlib.machinery import SourceFileLoader
from pathlib import Path
p=Path(__file__).parent;m=SourceFileLoader('tle',str(p/'author-helper.py')).load_module()
ACT='Gabay na 30 minuto: 10 pag-unawa sa teksto, 8 pag-aayos ng halimbawa, 9 pagsulat, 3 pagbalik-tanaw.\n'
m.lesson(73,'Analog scale, clamp, at measurement error','Sukatin matapos itugma ang range, function, at epekto sa circuit.',[
('Range at scale nang magkasama','Basahin ang analog meter sa scale ng piniling range. Kung20 sa full-scale50 at25mA range,10mA ang basa. Nonlinear ang resistance scale at may multiplier; tiyakin ang zero adjustment bawat range change. Itapat ang mirror at pointer upang bawasan ang parallax.'),('Suriin ang function ng modelo','May DMM na direktang sumusukat ng AC current; huwag sabihing walang tester na kaya. Sinusukat ng clamp meter ang current sa pagpalibot sa conductor; tingnan ang method,AC/DC,conductor,at rating. Hindi direktang power ang current lamang.'),('Epekto sa circuit','Sa voltage-drop R=V/I, may epekto ang lead,contact,meter resistance. Binabago rin ng voltmeter input at ammeter insertion ang circuit; hindi display lamang ang true value. Sa oscilloscope, tingnan din ang bandwidth,sample rate,memory,probe.')],['Paglihis ng basa dahil sa posisyon ng tingin.','Meter na pumapalibot sa conductor upang sukatin ang current.','Resistance sa input ng meter.','Bilang ng pagkuha ng signal bawat unit time.'],ACT+'Kunin ang basa sa full-scale100,range5V,indication64. Ipaliwanag ang lead resistance sa resistance measurement at input resistance sa voltage measurement.',['Sundin ang assigned procedure,rating,at safety conditions pati sa clamp/probe attachment.'],'Sukatin matapos itugma ang range, function, at epekto sa circuit.')
m.lesson(74,'Pag-aayos at handover pagkatapos assembly','Ang pag-aayos ay yugto ng pagtiyak sa dami, foreign matter, at state bago handover.',[
('Paghahanda at pagkapagod','Ihanda ang damit,tools,parts,work surface,ilaw,procedure,static control,ventilation,cooling. Kahit sanay,bumababa ang atensiyon sa pagod;kaya sundin ang break plan. Piliin ang PPE sa panganib at iwasan ang mahihila sa rotating parts.'),('Ibalik ang dami at kondisyon','Ibalik sa lugar ang tools,remaining parts,documents at alisin sa takdang gamit ang solder debris/cuttings. Tingnan ang foreign matter sa board/housing at ihiwalay ang held/good products. Huwag iwan lahat sa palagay na pareho ang susunod na trabaho.'),('Records para sa susunod na pasya','Itala ang part number,lot,dami,completed scope,unfinished work,equipment state,abnormalities/actions,recipient. Kung hindi tugma ang remaining count,huwag piliting balansehin;ulat ng possible mix/missing. Panatilihin ang isolation/residual-heat care sa cleaning.')],['Pagsabi ng state at kailangang impormasyon sa susunod na nakatalaga.','Bagay na hindi dapat nasa produkto/proseso.','Daming natira matapos gamitin/iproseso.','Produktong hiwalay na naghihintay ng hatol o aksiyon.'],ACT+'Gumawa ng end record ng planned32,completed25,held2,not started5 at handover kapag kulang ang1tool.',['Huwag ipasok ang kamay sa umaandar na loob para maglinis o kumuha ng tool.'],'Ang pag-aayos ay yugto ng pagtiyak sa dami, foreign matter, at state bago handover.')
m.lesson(75,'Pagtiyak ng logic laws sa truth table','Linawin ang operation symbols at saklaw ng negation at check sa lahat ng inputs.',[
('Order ng parehong operation','Sa binary logic,＋ang OR,・ang AND,NOT ang negation. Sa commutative/associative laws,pareho kahit iba ang order/brackets ng parehong operation. Iba sa ordinaryong arithmetic:x+x=x,x・x=x.'),('0,1,negation','x+0=x,x・1=x,x+1=1,x・0=0. Sa NOT x,x+NOT x=1,x・NOT x=0;double negation ayx. Absorption x+x・y=x at distributive x・(y+z)=x・y+x・z ay mache-check sa apat/o walong input combinations.'),('Saklaw ng negation','De Morgan:NOT(x+y)=(NOT x)・(NOT y);NOT(x・y)=(NOT x)+(NOT y). Ipakita sa brackets ang saklaw. Kahit mapaiikli ang expression,hiwalay na suriin ang failure behavior at safety.')],['Table ng bawat input combination at logic result.','Logic law sa pagsasaayos ng overlapping conditions.','Law ng pag-expand ng operation sa loob/labas ng brackets.','Pagbalik sa original value matapos dalawang negation.'],ACT+'Gumawa ng four-row table ng x+x・y at isang input kung saan magkaiba ang NOT(x+y) at NOT x+NOT y.',['Huwag aprubahan ang safety-circuit change mula logical equivalence lamang.'],'Linawin ang operation symbols at saklaw ng negation at check sa lahat ng inputs.')
m.lesson(76,'Switch,sensor,relay,at SSR','Kilalanin ang parts nang hiwalay ang detection principle at output method.',[
('Input-producing parts','May automatic-return at maintained pushbuttons. Mechanical limit switch ang nagbabago ng contact sa object motion;photoelectric/proximity sensors ay ibang principles. Sa float/pressure,tingnan din ang detected quantity at output type.'),('Switching sa electromagnetism','Coil magnetism ang nagpapagalaw ng relay armature/contacts. Contactor para sa malaking load switching,ngunit hindi laging may short/overcurrent protection mag-isa. Itugma ang coil rating,contact capacity,a/b,device number.'),('Ihiwalay ang semiconductor output','SSR ay pangunahing semiconductor switching,kaya hindi lahat ng relay ay mechanical contact/coil lamang. Tingnan ang off leakage,heat,load sa specs. Hindi safety certification ng buong equipment ang emergency button shape/contact lamang.')],['Switch na nagpapalit ng contact sa object position/motion.','Device na gumagamit ng electromagnetism sa load switching.','Relay na gumagamit ng semiconductor switching.','Pagbalik sa original state kapag binitiwan ang operation.'],ACT+'Ihambing ang input,principle,rating ng pushbutton,position detection,relay,SSR. Sumulat ng non-detection report na walang basta wiring change.',['Huwag i-short ang detector o emergency-stop signal upang paandarin.'],'Kilalanin ang parts nang hiwalay ang detection principle at output method.')
m.lesson(77,'Thermal relay at timer state changes','Ihiwalay ang overload detection,main-circuit switching,at time control.',[
('Overload detection','Thermal relay ay gumagamit ng init mula overcurrent at bimetal upang detect overload. Bimetal ang pinagsamang metals na magkaiba ang thermal expansion. Hindi ito stand-alone main-circuit breaker;karaniwang kasama ang contactor.'),('Delayed on','Basic on-delay:output on matapos setting mula input on;output off sa input off. Sa basic example,walang output kung mas maikli ang input kaysa setting. Tingnan bawat contact kung instantaneous return o delayed operation.'),('Delayed off','Basic off-delay:output sa input on;off matapos setting mula input off. Iba ang hold at supply conditions sa produkto;huwag ipalagay na pareho sa power loss. Iguhit ang input/output sa magkahiwalay na linya sa time axis.')],['Relay na gumagamit ng init upang detect overload.','Pinagdikit na metals na magkaiba ang thermal expansion.','Delayed output on mula input on.','Delayed output off mula input off.'],ACT+'Ipaliwanag ang output ng setting3seconds on-delay na input2at5seconds at ihambing ang time matapos input end ng off-delay.',['Huwag mag-reset laban sa protective operation o basta palitan ang timer setting.'],'Ihiwalay ang overload detection,main-circuit switching,at time control.')
m.lesson(78,'Synchronous speed,mechanical output,at starting methods','Hiwalay na basahin ang synchronous/actual speed,input,at shaft output.',[
('Field speed at rotor','Synchronous speed ng rotating field ay Ns=120f/p. Sa50Hz・4poles,1500min⁻¹;karaniwang mas mabagal ang loaded induction rotor at may slip. Hindi unconditional actual-speed guarantee ang formula.'),('Output mula torque','Shaft power P=2πNT/60,N actual rpm min⁻¹,T N·m. Sa600min⁻¹ at2N·m,humigit-kumulang126W. Ihiwalay ang input at shaft output kasama ang losses;hindi pahintulot lumampas sa rating ang computed power.'),('Starting conditions','Piliin ang full-voltage,star-delta,compensator,reactor sa gamit/equipment. May winding/connection assumptions ang star-delta current reduction. Huwag sariling palit ng terminals;tingnan ang starting current,load,protection.')],['Rotating-field speed ayon sa supply frequency at poles.','Daming nagpapahayag ng difference ng synchronous at rotor speed.','Mechanical output mula shaft.','Pagsisimula mula stopped state.'],ACT+'Kunin ang synchronous speed sa60Hz・6poles at ipaliwanag kung bakit hindi pareho sa measured980min⁻¹. Kalkulahin ang shaft output sa900min⁻¹・4N·m.',['Huwag basta baguhin ang terminals/phase sequence upang subukan ang speed/direction.'],'Hiwalay na basahin ang synchronous/actual speed,input,at shaft output.')
m.lesson(79,'Transformer losses,insulation,at environment','Ihiwalay ang loss at insulation structure at sundin ang protection,maintenance,environment.',[
('Paano lumalaki ang losses','Core loss ay pangunahing sa core;mayroon kahit walang secondary load kung primary voltage sa rated conditions. Copper loss ay I²R sa winding;sa parehong R,2current ay4loss. May stray-load losses;kaya hindi ideal ratio lamang ang efficiency.'),('Insulation/cooling materials','Iba ang structure/maintenance ng oil-filled,molded,gas-insulated. SF6 ay insulation-gas example,ngunit malaki ang environmental impact at hindi basta ilalabas. Huwag ligtas dahil colorless/odorless;gamitin ang equipment/material info.'),('Protection at system','Tingnan sa specs ang breaker arc medium/insulation. Huwag gawing general claim na wala nang old methods;tingnan ang actual nameplate/procedure. Solar DCconversion/storage ay system kasama ang destination/protection.')],['Loss sa winding resistance.','Loss sa magnetic core.','Dagdag na load loss mula leakage flux at iba pa.','Istruktura na resin at iba pa ang nagpapatigas sa insulation.'],ACT+'Kunin ang copper-loss ratio kung1.5ang load-current ratio sa parehong winding resistance. Ayusin ang maintenance/environment info sa oil,resin,gas equipment.',['Huwag basta alisin,buksan,o maglabas ng insulating oil/gas.'],'Ihiwalay ang loss at insulation structure at sundin ang protection,maintenance,environment.')
m.lesson(80,'Inspection stages,reliability,at electrical safety','Ihiwalay ang stage at layunin at gumamit ng tests na tugma sa equipment/conditions.',[
('Parts,board,finished product','Iba ang target ng incoming components,assembled board solder/orientation/electrical properties,at finished dimensions/function/appearance. Hindi dahilan ang supplier record upang laktawan ang required internal checks.'),('Environment at life','Environmental test ang takdang temperature,humidity,vibration,shock. Reliability test ay accelerated conditions at iba pa upang siyasatin ang quality maintenance;hindi lifespan guarantee ang isang maikling operation test.'),('Safety at electromagnetic tests','Magkaiba ang insulation resistance at withstand-voltage purposes/methods. Hindi laging mapapalitan ng general tester ang leakage at EMS checks. Itugma ang equipment,conditions,criteria,operator at itala ang results at standards.')],['Test ng operation/performance sa takdang humidity,temperature,vibration,at iba pa.','Katangiang nagpapanatili ng required function sa kinakailangang panahon.','Katangian ng insulation laban sa specified voltage.','Pananaw sa immunity sa electromagnetic interference.'],ACT+'Gumawa ng inspection record na hiwalay ang confirmed/unconfirmed sa normal appearance ngunit walang environmental test. Ipaliwanag kung bakit magkaiba ang insulation resistance/withstand-voltage.',['Huwag magdagdag ng withstand-voltage/safety tests nang walang approval.'],'Ihiwalay ang stage at layunin at gumamit ng tests na tugma sa equipment/conditions.')
